using System;
using System.IO;
using Newtonsoft.Json.Linq;
using XanaduYonder.Core.SlidingPuzzle;
using XanaduYonder.Runtime.SlidingPuzzle;
internal static class Program
{
    static int passed, failed;
    static void Main()
    {
        Check("records preserve real performance tuples and tiebreakers", () => { var r=new SlidingPuzzleRecord(); Assert(r.Consider(20,30)); r.Consider(30,10); Equal(r.BestMoves.Moves,20); Equal(r.BestMoves.Seconds,30); Equal(r.BestTime.Moves,30); Equal(r.BestTime.Seconds,10); r.Consider(20,25); Equal(r.BestMoves.Seconds,25); r.Consider(25,10); Equal(r.BestTime.Moves,25); Assert(!r.Consider(25,10)); Reject(()=>r.Consider(0,1)); Reject(()=>r.Consider(1,double.NaN)); });
        Check("timer starts on first legal move and pauses for every gate", () => { var s=Session(); s.Tick(5); Equal(s.ElapsedSeconds,0); Assert(!s.Move(1)); s.Tick(5); Equal(s.ElapsedSeconds,0); Assert(s.Move(5)); s.Tick(2); Equal(s.ElapsedSeconds,2); s.SetBlocked(true); Assert(!s.Move(8)); Assert(!s.Undo()); s.Tick(5); s.SetBlocked(false); s.SetForeground(false); Assert(!s.Move(8)); s.Tick(5); s.SetForeground(true); s.Leave(); Assert(!s.Undo()); s.Tick(5); s.Enter(); s.Tick(3); Equal(s.ElapsedSeconds,5); Reject(()=>s.Tick(double.NaN)); Reject(()=>s.Tick(-1)); });
        Check("terminal stops timer and restart resets attempt while preserving gates", () => { var s=new SlidingPuzzleSession(new SlidingPuzzleGame(3,new[]{1,2,3,4,5,6,7,0,8})); Assert(s.Move(8)); s.Tick(5); Equal(s.ElapsedSeconds,0); Assert(!s.Undo()); s.SetBlocked(true); s.SetForeground(false); s.Leave(); s.Restart(); Equal(s.Game.Moves,0); Equal(s.ElapsedSeconds,0); Assert(!s.ResultRecorded&&!s.IsNewBest&&!s.Active&&!s.Foreground); Assert(s.Game.GetInitial()[7]==0); });
        Check("free 3 4 5 and campaign resume independently without phantom progress", () => { var p=new SlidingPuzzleProfile(); Equal(p.SelectedSize,4); Equal(p.CompletedCount,0); var a=p.StartFree(3); int tile=Neighbor(a.Game); Assert(a.Move(tile)); a.Tick(2); var b=p.StartFree(4); Assert(!a.Active&&b.Active); var c=p.StartFree(5); Assert(ReferenceEquals(a,p.StartFree(3))); Equal(a.ElapsedSeconds,2); Equal(a.Game.Moves,1); p.SelectMode(1); Assert(p.ActiveSession==null&&!a.Active); Equal(p.CompletedCount,0); Assert(!p.SelectChapter(1)); Reject(()=>p.StartLevel(6)); var level=p.StartLevel(0); Assert(level.Active); Assert(ReferenceEquals(c,p.StartFree(5))); Assert(ReferenceEquals(level,p.StartLevel(0))); Assert(!ReferenceEquals(a,p.StartFree(3,true))); Equal(p.CompletedCount,0); });
        Check("all 18 levels unlock sequentially and repeated wins are idempotent", () => { var p=new SlidingPuzzleProfile(); for(int i=0;i<18;i++){ Assert(p.IsLevelUnlocked(i)); if(i<17) Assert(!p.IsLevelUnlocked(i+1)); var s=p.StartLevel(i); foreach(int tile in SlidingPuzzleCatalog.Get(i).Solution) Assert(s.Move(tile)); Assert(s.Game.Won); Assert(p.RecordCompleted()); Assert(!p.RecordCompleted()); Equal(p.CompletedCount,i+1); Assert(p.GetLevelRecord(i)!=null); p.Capture(); Equal(p.CompletedCount,i+1); } Assert(p.IsChapterUnlocked(2)); var restored=new SlidingPuzzleProfile(Roundtrip(p.Export())); Equal(restored.CompletedCount,18); Assert(!restored.RecordCompleted()); });
        Check("assisted wins unlock but never enter unassisted records", () => { var p=new SlidingPuzzleProfile(); var s=p.StartLevel(0); int first=SlidingPuzzleCatalog.Get(0).Solution[0]; Assert(s.Move(first)); Assert(s.Undo()); foreach(int tile in SlidingPuzzleCatalog.Get(0).Solution) Assert(s.Move(tile)); Assert(s.Game.Assisted); p.Capture(); Equal(p.CompletedCount,1); Assert(p.GetLevelRecord(0)==null); s=p.StartLevel(0,true); foreach(int tile in SlidingPuzzleCatalog.Get(0).Solution) Assert(s.Move(tile)); p.Capture(); Assert(p.GetLevelRecord(0)!=null); Equal(p.CompletedCount,1); });
        Check("roundtrip preserves full history undo counts timing and deep copies", () => { var p=new SlidingPuzzleProfile(); var s=p.StartLevel(0); int tile=SlidingPuzzleCatalog.Get(0).Solution[0]; Assert(s.Move(tile)); s.Tick(4); Assert(s.Undo()); Assert(s.Move(tile)); var d=Roundtrip(p.Capture()); var copy=d.Copy(); copy.CampaignSession.Snapshot.Cells[0]=-1; Assert(d.CampaignSession.Snapshot.Cells[0]>=0); var loaded=new SlidingPuzzleProfile(d); Equal(loaded.ActiveSession.ElapsedSeconds,4); Equal(loaded.ActiveSession.Game.Moves,3); Equal(loaded.ActiveSession.Game.UndoCount,1); Assert(loaded.ActiveSession.Undo()); Equal(loaded.ActiveSession.Game.Moves,4); });
        Check("required root session and snapshot fields reject missing null wrong types", () => { var valid=Valid(); var source=JObject.Parse(valid); foreach(string path in new[]{"","campaignSession","campaignSession.snapshot"}){var obj=path.Length==0?source:(JObject)source.SelectToken(path); foreach(var prop in obj.Properties()){ foreach(int mode in new[]{0,1,2}){if(path.Length==0&&prop.Name=="campaignSession"&&mode==1)continue; var root=JObject.Parse(valid); var target=path.Length==0?root:(JObject)root.SelectToken(path); if(mode==0)target.Remove(prop.Name); else target[prop.Name]=mode==1?JValue.CreateNull():(prop.Value.Type==JTokenType.Array?(JToken)new JValue("wrong"):new JArray()); Bad(root.ToString()); }}} });
        Check("strict JSON duplicate keys versions depth length and numeric types", () => { var valid=Valid(); Bad(valid.Replace("\"schemaVersion\":1","\"schemaVersion\":1,\"schemaVersion\":1")); Bad(valid.Replace("\"schemaVersion\":1","\"schemaVersion\":2")); Bad(valid.Replace("\"contentVersion\":\"1\"","\"contentVersion\":\"future\"")); Bad(valid.Replace("\"saveKind\":\"sliding-puzzle\"","\"saveKind\":\"sokoban\"")); Bad("/*x*/"+valid); Bad(valid.Replace("\"saveKind\"","'saveKind'")); Bad(valid.TrimEnd('}')+",}"); Bad(valid+" true"); Bad(new string('[',20)+new string(']',20)); Bad(new string(' ',SlidingPuzzleSaveCodec.MaximumLength+1)); Mutate(r=>r["selectedSize"]=4.0); Mutate(r=>r["campaignSession"]["elapsedSeconds"]="1"); Mutate(r=>r["campaignSession"]["elapsedSeconds"]=-1); Bad(valid.Replace("\"elapsedSeconds\":0.0","\"elapsedSeconds\":1e999")); });
        Check("restore rejects illegal boards history counts and mismatched catalog initial", () => { Mutate(r=>r["campaignSession"]["snapshot"]["cells"][0]=99); Mutate(r=>r["campaignSession"]["snapshot"]["moves"]=1); Mutate(r=>r["campaignSession"]["snapshot"]["undoCount"]=-1); Mutate(r=>r["campaignSession"]["snapshot"]["history"]=new JArray(999)); Mutate(r=>r["campaignSession"]["snapshot"]["initialCells"]=new JArray(1,2,3,4,5,6,0,7,8)); Mutate(r=>r["campaignSession"]["levelIndex"]=1); Mutate(r=>r["campaignSession"]["elapsedSeconds"]=1); Mutate(r=>r["campaignSession"]["resultRecorded"]=true); });
        Check("completion prefix and records reject contradictory accounting", () => { Mutate(r=>r["completedLevels"]=new JArray(1)); Mutate(r=>r["completedLevels"]=new JArray(0,2)); Mutate(r=>r["completedLevels"]=new JArray(0,0)); var p=new SlidingPuzzleProfile(); var s=p.StartLevel(0); foreach(int tile in SlidingPuzzleCatalog.Get(0).Solution)s.Move(tile); var json=SlidingPuzzleSaveCodec.Encode(p.Capture()); var root=JObject.Parse(json); root["completedLevels"]=new JArray(); Bad(root.ToString()); root=JObject.Parse(json); root["campaignSession"]["resultRecorded"]=false; Bad(root.ToString()); root=JObject.Parse(json); root["levelRecords"][0]=JValue.CreateNull(); Bad(root.ToString()); root=JObject.Parse(json); root["levelRecords"][0]["bestMoves"]["moves"]=100000; Bad(root.ToString()); });
        Check("active slot and selected chapter cannot refer to locked or wrong-sized games", () => { Mutate(r=>r["selectedChapter"]=2); Mutate(r=>r["freeSessions"][1]=r["campaignSession"].DeepClone()); Mutate(r=>r["campaignSession"]["levelIndex"]=6); Mutate(r=>r["freeSessions"]=new JArray()); });
        Check("score fields reject missing null wrong types and inconsistent tuples", () => { var p=new SlidingPuzzleProfile();var s=p.StartLevel(0);foreach(int tile in SlidingPuzzleCatalog.Get(0).Solution)s.Move(tile);string valid=SlidingPuzzleSaveCodec.Encode(p.Capture());foreach(string path in new[]{"levelRecords[0]","levelRecords[0].bestMoves","levelRecords[0].bestTime"}){var obj=(JObject)JObject.Parse(valid).SelectToken(path);foreach(var prop in obj.Properties())foreach(int mode in new[]{0,1,2}){var root=JObject.Parse(valid);var target=(JObject)root.SelectToken(path);if(mode==0)target.Remove(prop.Name);else target[prop.Name]=mode==1?JValue.CreateNull():(JToken)new JArray();Bad(root.ToString());}}var bad=JObject.Parse(valid);bad["levelRecords"][0]["bestTime"]["seconds"]=-1;Bad(bad.ToString());bad=JObject.Parse(valid);bad["levelRecords"][0]["bestTime"]["seconds"]=100;Bad(bad.ToString()); });
        Check("four full action-limit histories fit and roundtrip without truncation", () => { var p=new SlidingPuzzleProfile();p.StartFree(3);p.StartFree(4);p.StartFree(5);p.StartLevel(0);var d=p.Capture();foreach(var item in new[]{d.FreeSessions[0],d.FreeSessions[1],d.FreeSessions[2],d.CampaignSession}){int tile=LoopTile(item.Snapshot);item.Snapshot.History=new int[SlidingPuzzleGame.MaxActions];for(int i=0;i<item.Snapshot.History.Length;i++)item.Snapshot.History[i]=tile;item.Snapshot.Moves=SlidingPuzzleGame.MaxActions;item.ElapsedSeconds=10;}string json=SlidingPuzzleSaveCodec.Encode(d);Assert(System.Text.Encoding.UTF8.GetByteCount(json)<SlidingPuzzleSaveCodec.MaximumLength);var restored=Roundtrip(d);var loaded=new SlidingPuzzleProfile(restored);Assert(loaded.ActiveSession.Game.AtActionLimit);Assert(!loaded.ActiveSession.Move(LoopTile(restored.CampaignSession.Snapshot)));Assert(!loaded.ActiveSession.Undo());loaded.ActiveSession.Tick(20);Equal(loaded.ActiveSession.ElapsedSeconds,10);foreach(var item in restored.FreeSessions)Equal(item.Snapshot.History.Length,SlidingPuzzleGame.MaxActions);var bad=JObject.Parse(json);((JArray)bad["campaignSession"]["snapshot"]["history"]).Add(1);Bad(bad.ToString()); });
        Check("time cap and invalid numeric deltas remain finite", () => {var s=Session();Assert(s.Move(5));s.Tick(double.MaxValue);Equal(s.ElapsedSeconds,SlidingPuzzleSessionData.MaximumSeconds);s.Tick(double.MaxValue);Equal(s.ElapsedSeconds,SlidingPuzzleSessionData.MaximumSeconds);Reject(()=>s.Tick(double.PositiveInfinity));var valid=Valid();Bad(valid.Replace("\"contentVersion\":\"1\"","\"contentVersion\":\""+new string('中',750000)+"\"")); });
        Check("store atomic saves backup recovery and corrupt main preservation",()=>WithDirectory(dir=>{var store=new SlidingPuzzleSaveStore(dir);Assert(store.Load(out var warning)==null&&warning==null);var p=new SlidingPuzzleProfile();Assert(store.TrySave(p.Capture(),out var error),error);p.StartLevel(0);Assert(store.TrySave(p.Capture(),out error),error);string backup=File.ReadAllText(store.SavePath+".bak");File.WriteAllText(store.SavePath,"broken");var recovery=new SlidingPuzzleSaveStore(dir);var d=recovery.Load(out warning);Assert(d!=null&&warning!=null);Assert(recovery.TrySave(d,out error),error);Assert(File.ReadAllText(store.SavePath+".bak")==backup);Assert(Directory.GetFiles(dir,"*.corrupt-*").Length>0);Assert(new SlidingPuzzleSaveStore(dir).Load(out warning)!=null);}));
        Check("external corruption never replaces valid backup and failed writes preserve main",()=>WithDirectory(dir=>{var store=new SlidingPuzzleSaveStore(dir);var d=new SlidingPuzzleProfile().Capture();Assert(store.TrySave(d,out var error),error);Assert(store.TrySave(d,out error),error);string backup=File.ReadAllText(store.SavePath+".bak");File.WriteAllText(store.SavePath,"external corruption");Assert(store.TrySave(d,out error),error);Assert(File.ReadAllText(store.SavePath+".bak")==backup);string before=File.ReadAllText(store.SavePath);Directory.CreateDirectory(store.SavePath+".tmp");Assert(!store.TrySave(d,out error)&&error!=null);Assert(File.ReadAllText(store.SavePath)==before);Directory.Delete(store.SavePath+".tmp");Assert(store.TrySave(d,out error),error);}));
        Check("invalid UTF8 is rejected and invalid exports cannot replace old save",()=>WithDirectory(dir=>{var store=new SlidingPuzzleSaveStore(dir);File.WriteAllBytes(store.SavePath,new byte[]{0xff,0xfe});Assert(store.Load(out var warning)==null&&warning!=null);var d=new SlidingPuzzleProfile().Capture();Assert(store.TrySave(d,out var error),error);string before=File.ReadAllText(store.SavePath);d.FreeSessions[1].Snapshot.Cells[0]=-1;Assert(!store.TrySave(d,out error)&&error!=null);Assert(File.ReadAllText(store.SavePath)==before);}));
        Console.WriteLine("Sliding puzzle persistence/session: "+passed+" passed, "+failed+" failed"); if(failed!=0)Environment.Exit(1);
    }
    static SlidingPuzzleSession Session(){return new SlidingPuzzleSession(new SlidingPuzzleGame(3,new[]{1,2,3,4,0,5,7,8,6}));}
    static int LoopTile(SlidingPuzzleSnapshot snapshot){foreach(int tile in snapshot.InitialCells){var probe=new SlidingPuzzleGame(snapshot.Size,snapshot.InitialCells);if(probe.TryMove(tile)&&!probe.Won)return tile;}throw new Exception("No nonterminal adjacent move");}
    static int Neighbor(SlidingPuzzleGame game){var c=game.GetCells();int blank=Array.IndexOf(c,0);return c[blank%game.Size==0?blank+1:blank-1];}
    static string Valid(){var p=new SlidingPuzzleProfile();p.StartLevel(0);return SlidingPuzzleSaveCodec.Encode(p.Capture());}
    static SlidingPuzzleSaveData Roundtrip(SlidingPuzzleSaveData data){Assert(SlidingPuzzleSaveCodec.TryDecode(SlidingPuzzleSaveCodec.Encode(data),out var restored,out var why),why);return restored;}
    static void Mutate(Action<JObject> mutate){var root=JObject.Parse(Valid());mutate(root);Bad(root.ToString());}
    static void Bad(string json){Assert(!SlidingPuzzleSaveCodec.TryDecode(json,out var d,out var why),"Accepted invalid: "+json.Substring(0,Math.Min(json.Length,180)));Assert(d==null&&why!=null);}
    static void WithDirectory(Action<string> action){string dir=Path.Combine(Path.GetTempPath(),"sliding-puzzle-check-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(dir);try{action(dir);}finally{Directory.Delete(dir,true);}}
    static void Check(string name,Action run){try{run();passed++;Console.WriteLine("PASS "+name);}catch(Exception e){failed++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
    static void Equal(double a,double b){Assert(a==b,a+" != "+b);}
    static void Assert(bool value,string message="Assertion failed"){if(!value)throw new Exception(message);}
    static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Expected argument rejection");}
}
